<?php
declare(strict_types=1);
require __DIR__ . '/auth.php';
mulai_sesi();
header('Cache-Control: no-store');

// Sudah login? langsung ke halaman utama
if (sudah_login()) {
    alihkan(HALAMAN_UTAMA);
}

$pesan    = '';      // pesan kecil di bawah tombol
$modal    = null;    // pop up: ['judul' => ..., 'fokus' => 'u'|'p', 'isi' => teks khusus (opsional)]
$username = '';

if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    $username = strtolower(trim((string)($_POST['username'] ?? '')));
    $password = (string)($_POST['password'] ?? '');
    $ingat    = isset($_POST['ingat']);

    if (!csrf_valid((string)($_POST['csrf'] ?? ''))) {
        $pesan = 'Sesi formulir kedaluwarsa. Muat ulang halaman lalu coba lagi.';
    } elseif ($username === '' || $password === '') {
        $pesan = 'Isi nama pengguna dan kata sandi terlebih dahulu.';
    } elseif (sisa_kunci() > 0) {
        $menit = (int)ceil(sisa_kunci() / 60);
        $modal = [
            'judul' => 'Terlalu Banyak Percobaan',
            'fokus' => 'u',
            'isi'   => "Silakan coba lagi sekitar {$menit} menit lagi.",
        ];
    } else {
        $p = cari_pengguna($username);                       // baca tabel pengguna
        if ($p === null) {
            catat_gagal();
            $modal = ['judul' => 'Nama Pengguna Tidak Dikenal', 'fokus' => 'u'];
        } elseif (!password_verify($password, $p['hash'])) {
            catat_gagal();
            $modal = ['judul' => 'Password Anda Salah', 'fokus' => 'p'];
        } else {
            login_berhasil($username, $p, $ingat);           // buat sesi
            alihkan(HALAMAN_UTAMA);
        }
    }
}
?>
