<script>
/* Autentikasi dilakukan di server (login.php + auth.php). Skrip ini hanya untuk tampilan. */
const f=document.getElementById('f'),u=document.getElementById('u'),p=document.getElementById('p'),t=document.getElementById('t'),
      m=document.getElementById('msg'),modal=document.getElementById('modal'),closeBtn=document.getElementById('close');

t.addEventListener('click',()=>{const s=p.type==='password';p.type=s?'text':'password';t.textContent=s?'Sembunyikan':'Tampilkan';t.setAttribute('aria-label',s?'Sembunyikan kata sandi':'Tampilkan kata sandi')});

function hideModal(){
  modal.classList.remove('show');
  const el=document.getElementById(modal.dataset.fokus||'u');if(el)el.focus();
}
closeBtn.addEventListener('click',hideModal);
modal.addEventListener('click',e=>{if(e.target===modal)hideModal()});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&modal.classList.contains('show'))hideModal()});
if(modal.classList.contains('show'))closeBtn.focus();

f.addEventListener('submit',e=>{
  if(!u.value.trim()||!p.value){e.preventDefault();m.textContent='Isi nama pengguna dan kata sandi terlebih dahulu.'}
});
</script>
